#include <iostream>
using namespace std;

long long binomial(int n, int r) {
    r = min(r, n - r);
    long long result = 1;
    for (int i = 1; i <= r; ++i) {
        result = result * (n - r + i) / i;
    }
    return result;
}

long long a(int n) {
    return binomial(2 * n, n) - 1;
}

int main() {
    int x;
    cin >> x;
    cout << a(x + 1) << '\n';
    return 0;
}

#include <iostream>
#include <boost/multiprecision/cpp_int.hpp>

using boost::multiprecision::cpp_int;

cpp_int binomial(int n, int r) {
    if (r > n - r) r = n - r;
    cpp_int result = 1;
    for (int i = 1; i <= r; ++i) {
        result *= n - r + i;
        result /= i;
    }
    return result;
}

int main() {
    int x;
    std::cin >> x;
    int n = x + 1;
    std::cout << binomial(2 * n, n) - 1 << '\n';
    return 0;
}

